-- amkhoib-contractor-consultants-pty-ltd-buffelsdrift (researched)
UPDATE businesses SET description = 'AMKHOIB Contractor Consultants protects construction businesses from costly safety violations and workplace incidents, handling health and safety documentation, compliance and risk management so contractors can focus on delivering their projects. Its services cover contractor health and safety specifications, documentation compilation, ongoing management assistance, training and information sessions, and incident investigation when something does go wrong.

The company backs this with monthly on-site inspections and documentation audits, aiming to keep contractors legislatively compliant and reduce liability and insurance risk over the life of a project, rather than just at the point of sign-off. Operating from offices in Pretoria, Cape Town and Durban, AMKHOIB Contractor Consultants positions itself as a specialist in construction-industry safety compliance across these regions.', source_urls = json_insert(CASE WHEN json_valid(source_urls) AND json_type(source_urls) = 'array' THEN source_urls ELSE '[]' END, '$[#]', 'https://amkhoib.com/'), description_enriched_at = datetime('now') WHERE slug = 'amkhoib-contractor-consultants-pty-ltd-buffelsdrift' AND description = 'AMKHOIB Contractor Consultants is a health and safety compliance consultancy for the construction industry, compiling safety documentation and carrying out site inspections, audits, incident investigations and training for contractors from its Pretoria head office.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
  AND owner_user_id IS NULL AND COALESCE(subscription_tier, 0) = 0 AND COALESCE(origin, '') != 'owner_submitted'
  AND status = 'published' AND closed_at IS NULL AND is_test = 0
  AND custom_blocks IS NULL AND page_html IS NULL
  AND NOT EXISTS (SELECT 1 FROM business_claims c WHERE c.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM subscriptions s WHERE s.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM business_photos p WHERE p.business_id = businesses.id);
-- amphi-human-capital-development-wierdapark (researched)
UPDATE businesses SET description = 'AMPHI Human Capital Development holds a Level 2 B-BBEE status, with 51% Black ownership and 31% Black women ownership, and delivers accredited training to corporate customers across South Africa in a range of industries. The organisation offers more than 45 historical SETA and QCTO accredited qualifications spanning multiple skill levels, aiming to develop individuals rather than deliver training for its own sake.

Its stated mission is to set the standard for impactful education and training, built around values of integrity, trust and creating win-win outcomes for both learners and the businesses that send them. Based in Wierdapark, Centurion, AMPHI Human Capital Development works to keep its course offering aligned with changes in the skills landscape, supporting both individual learner development and employer compliance needs.', source_urls = json_insert(CASE WHEN json_valid(source_urls) AND json_type(source_urls) = 'array' THEN source_urls ELSE '[]' END, '$[#]', 'http://amphisa.co.za/about-us'), description_enriched_at = datetime('now') WHERE slug = 'amphi-human-capital-development-wierdapark' AND description = 'AMPHI Human Capital Development is a Centurion-based skills development and BEE compliance consultancy, part of Audit BEE Inc (founded 2015), offering auditing, payroll, Employment Equity compliance and workplace skills plan services alongside learnership programmes.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
  AND owner_user_id IS NULL AND COALESCE(subscription_tier, 0) = 0 AND COALESCE(origin, '') != 'owner_submitted'
  AND status = 'published' AND closed_at IS NULL AND is_test = 0
  AND custom_blocks IS NULL AND page_html IS NULL
  AND NOT EXISTS (SELECT 1 FROM business_claims c WHERE c.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM subscriptions s WHERE s.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM business_photos p WHERE p.business_id = businesses.id);
